import sys
from collections import deque

def bfs(graph, start, max_vertices):
    visited = set()
    queue = deque([start])
    path = []
    while queue and len(path) <= max_vertices:
        vertex = queue.popleft()
        if vertex not in visited:
            visited.add(vertex)
            path.append(vertex)
            for neighbor in graph[vertex]:
                if neighbor not in visited:
                    queue.append(neighbor)
    return path

